{"content":"using System.IO;
using System.Threading;

using LetUsCook.AutoWrongCensus.HostedServices;
using LetUsCook.AutoWrongCensus.Options;

using Microsoft.Extensions.DependencyInjection;

namespace LetUsCook.AutoWrongCensus;

/// <summary>
/// Console entry point for the F-428 P12.13 auto-wrong census: builds the Generic Host graph and
/// returns the hosted service's exit code, exactly the <c>tools/LetUsCook.Replay</c> shape. Tests
/// and <c>Program.cs</c> both run through here, so the golden TSV is produced by the same path the
/// CLI uses.
/// </summary>
public static class AutoWrongCensusCli
{
	/// <summary>Runs one census or pairs invocation and returns the process exit code.</summary>
	/// <param name="args">The raw command-line arguments.</param>
	/// <param name="output">Override for the TSV sink; defaults to <see cref="System.Console.Out"/>.</param>
	/// <param name="error">Override for the summary/error sink; defaults to <see cref="System.Console.Error"/>.</param>
	/// <param name="cancellationToken">Cooperative cancellation token.</param>
	/// <returns><c>0</c> on success; <c>1</c> on a missing trace, a refused set, or bad arguments.</returns>
	public static async Task<int> RunAsync(
		string[] args,
		TextWriter? output = null,
		TextWriter? error = null,
		CancellationToken cancellationToken = default)
	{
		ArgumentNullException.ThrowIfNull(args);
		if (Array.Exists(args, a => a.Equals("--help", StringComparison.OrdinalIgnoreCase) || a.Equals("-h", StringComparison.OrdinalIgnoreCase)))
		{
			AutoWrongCensusUsage.Print();
			return 0;
		}

		var builder = AutoWrongCensusHostBuilderFactory.Create(args, output, error);
		using var host = builder.Build();

		var hostedService = host.Services.GetRequiredService<AutoWrongCensusHostedService>();
		await host.RunAsync(cancellationToken).ConfigureAwait(false);
		return hostedService.ExitCode;
	}
}
