{"content":"namespace LetUsCook.AutoWrongCensus.Options;

/// <summary>Maps the positional subcommand syntax to configuration keys. Unknown shapes bind nothing,
/// and the runner then prints usage and exits 1.</summary>
public static class CommandLineArgumentParser
{
	/// <summary>The <c>census</c> subcommand name.</summary>
	public const string CensusCommand = "census";

	/// <summary>The <c>pairs</c> subcommand name.</summary>
	public const string PairsCommand = "pairs";

	/// <summary>Parses <c>census &lt;trace.jsonl&gt;</c> or <c>pairs &lt;census.tsv&gt; &lt;trace.jsonl&gt;</c>.</summary>
	/// <param name="args">Raw CLI arguments.</param>
	/// <returns>Configuration keys, or an empty dictionary when the shape is not one of the two subcommands.</returns>
	public static Dictionary<string, string?> Parse(string[] args)
	{
		ArgumentNullException.ThrowIfNull(args);
		var dict = new Dictionary<string, string?>(StringComparer.OrdinalIgnoreCase);

		if (args.Length == 2 && args[0].Equals(CensusCommand, StringComparison.OrdinalIgnoreCase))
		{
			dict["AutoWrongCensus:Command"] = CensusCommand;
			dict["AutoWrongCensus:TracePath"] = args[1];
		}
		else if (args.Length == 3 && args[0].Equals(PairsCommand, StringComparison.OrdinalIgnoreCase))
		{
			dict["AutoWrongCensus:Command"] = PairsCommand;
			dict["AutoWrongCensus:CensusTsvPath"] = args[1];
			dict["AutoWrongCensus:TracePath"] = args[2];
		}

		return dict;
	}
}
