/// <param name="OverrideKey">For the override site: <c>yes</c>/<c>no</c> — whether the normalised rawText is a key in <c>exact-overrides.json</c>; empty otherwise.</param>
/// <param name="AcceptedTier">Dataset tier of the accepted row.</param>
/// <param name="KeyTier">Dataset tier of the key row.</param>
