{"content":"using System.Collections.Frozen;
using System.IO;
using System.Reflection;
using System.Text.Json;

namespace LetUsCook.AutoWrongCensus.Services;

/// <summary>
/// Key set of <c>src/LetUsCook.Fdc/Lexicon/Resources/exact-overrides.json</c>, read from the
/// <c>LetUsCook.Fdc</c> assembly's embedded resource — the same file the matcher's override path is
/// built from (F-428 P6.3 folded it into <c>special-cases.json</c>; the brief asks for the
/// <c>exact-overrides.json</c> key membership specifically). Data only: no matching logic here.
/// </summary>
public sealed class ExactOverrideKeyIndex
{
	private static readonly JsonSerializerOptions JsonOptions = new(JsonSerializerDefaults.Web);

	private readonly FrozenSet<string> _keys;

	/// <summary>Loads the key set from the embedded <c>exact-overrides.json</c>.</summary>
	public ExactOverrideKeyIndex()
	{
		var assembly = typeof(LetUsCook.Fdc.Matching.FdcMatcher).Assembly;
		var resourceName = assembly.GetManifestResourceNames().Single(n => n.EndsWith("exact-overrides.json", StringComparison.Ordinal));
		using var stream = assembly.GetManifestResourceStream(resourceName)
			?? throw new InvalidOperationException($"Embedded resource '{resourceName}' not found.");
		using var reader = new StreamReader(stream);
		var entries = JsonSerializer.Deserialize<Dictionary<string, JsonElement>>(reader.ReadToEnd(), JsonOptions)
			?? throw new InvalidOperationException("exact-overrides.json was empty.");
		_keys = entries.Keys.ToFrozenSet(StringComparer.OrdinalIgnoreCase);
	}

	/// <summary>Returns true when <paramref name="key"/> is an <c>exact-overrides.json</c> key.</summary>
	/// <param name="key">The normalized raw line text.</param>
	/// <returns>Key membership.</returns>
	public bool Contains(string key) => _keys.Contains(key);

	/// <summary>
	/// Normalizes raw text for the override-key lookup the way the matcher folds it before
	/// <c>SpecialCases.TryGetRaw</c>: cut at the first parenthesis, trim, lowercase.
	/// (<c>FdcMatcher.StripFromParenthesis</c> is private; this is the one-line equivalent, cited in
	/// the report — the dictionary lookup itself is the shipped key set.)
	/// </summary>
	/// <param name="rawText">The raw line text.</param>
	/// <returns>The lookup key.</returns>
	public static string NormalizeForOverrideKey(string rawText)
	{
		ArgumentNullException.ThrowIfNull(rawText);
		var index = rawText.IndexOf('(', StringComparison.Ordinal);
		var cut = index >= 0 ? rawText[..index] : rawText;
		return cut.Trim().ToLowerInvariant();
	}
}
