{"content":"using System.Text.RegularExpressions;

using LetUsCook.AutoWrongCensus.Models;
using LetUsCook.Fdc;
using LetUsCook.Fdc.Lexicon;
using LetUsCook.Fdc.Matching;
using LetUsCook.Fdc.Parsing;
using LetUsCook.Fdc.Resolver;

namespace LetUsCook.AutoWrongCensus.Services;

/// <summary>
/// Classifies one auto-wrong trace line on two axes: the relation between the accepted row
/// (<c>actual*[0]</c>) and the labelled key row (<c>expected*[0]</c>), and the decision site the
/// line was accepted at. Every state/head/singularisation decision calls the production Fdc
/// helpers — <see cref="FdcNormalizer.NormalizeToTokens(string?)"/>,
/// <see cref="FdcMatcher.ExtractCandidateState(IReadOnlyList{string})"/>,
/// <see cref="FdcMatcher.ExtractCandidateSatisfiers(IReadOnlyList{string})"/>,
/// <see cref="FdcDescriptionParser.Parse(string, FdcDataset, string?)"/>,
/// <see cref="IngredientLineResolver.SingularizeToken(string)"/> — never a copy (D-014).
/// </summary>
public sealed partial class AutoWrongClassifier
{
	/// <summary>Relation: the trace carries no label.</summary>
	public const string RelationNoLabel = "no-label";

	/// <summary>Relation: rawText names a can/jar unit; the key row is Canned and the accepted row is not.</summary>
	public const string RelationPackUnitState = "pack-unit-state";

	/// <summary>Relation: the key head phrase is two or more words and parsedName is only its first word.</summary>
	public const string RelationCompoundHeadLost = "compound-head-lost";

	/// <summary>Relation: head terms agree and the state masks differ.</summary>
	public const string RelationStateMismatch = "state-mismatch";

	/// <summary>Relation: heads and state agree and the dataset tier differs.</summary>
	public const string RelationRowChoiceTier = "row-choice-tier";

	/// <summary>Relation: heads, state and tier agree; only qualifiers differ.</summary>
	public const string RelationSameHeadOtherQualifier = "same-head-other-qualifier";

	/// <summary>Relation: the head terms differ.</summary>
	public const string RelationSiblingFood = "sibling-food";

	/// <summary>Relation: nothing above holds, usually because a trace field the check needs is missing.</summary>
	public const string RelationOther = "other";

	/// <summary>Site: ranker path with <c>reused</c>.</summary>
	public const string SiteReuse = "reuse";

	/// <summary>Site: ranker path, not reused.</summary>
	public const string SiteRanker = "ranker";

	/// <summary>Site: override path.</summary>
	public const string SiteOverride = "override";

	/// <summary>Site: curated path.</summary>
	public const string SiteCurated = "curated";

	private static readonly StringComparer OrdinalIgnoreCaseComparer = StringComparer.OrdinalIgnoreCase;

	private readonly FdcNormalizer _normalizer;
	private readonly ExactOverrideKeyIndex _overrideKeys;
	private readonly List<string> _singleTokenScratch = new(1);

	/// <summary>Creates the classifier over the production normalizer and the override key index.</summary>
	/// <param name="normalizer">The production <see cref="FdcNormalizer"/>.</param>
	/// <param name="overrideKeys">Key set of <c>exact-overrides.json</c>.</param>
	public AutoWrongClassifier(FdcNormalizer normalizer, ExactOverrideKeyIndex overrideKeys)
	{
		ArgumentNullException.ThrowIfNull(normalizer);
		ArgumentNullException.ThrowIfNull(overrideKeys);
		_normalizer = normalizer;
		_overrideKeys = overrideKeys;
	}

	/// <summary>Classifies one trace line. Returns a result with an empty <c>Site</c> when the atom path is unknown.</summary>
	/// <param name="line">The trace line.</param>
	/// <returns>The relation, the site, and the row fields backing them.</returns>
	public ClassificationResult Classify(TraceLine line)
	{
		ArgumentNullException.ThrowIfNull(line);

		var atom = PickAtom(line.Atoms);
		var parsedTokens = SingularTokens(atom.ParsedName);
		var keyDesc = FirstOrEmpty(line.ExpectedDescriptions);
		var acceptedDesc = FirstOrEmpty(line.ActualDescriptions);
		var keyTier = FirstOrEmpty(line.ExpectedDataTypes);
		var acceptedTier = FirstOrEmpty(line.ActualDataTypes);
		var keyTokens = _normalizer.NormalizeToTokens(keyDesc);
		var acceptedTokens = _normalizer.NormalizeToTokens(acceptedDesc);
		var keyState = CombinedState(keyTokens);
		var acceptedState = CombinedState(acceptedTokens);
		var keyHeadPhrase = KeyHeadPhrase(keyTokens);

		var (site, overrideKey) = SiteFor(atom, line.RawText);

		var relation = RelationOther;
		string? missingField = null;
		IReadOnlyList<string>? keyOnlyQualifiers = null;
		IReadOnlyList<string>? acceptedOnlyQualifiers = null;

		if (string.IsNullOrWhiteSpace(keyDesc))
		{
			relation = RelationNoLabel;
		}
		else if (string.IsNullOrWhiteSpace(acceptedDesc))
		{
			missingField = "actualDescriptions";
		}
		else if (PackUnitRegex().IsMatch(line.RawText)
			&& (keyState & FoodState.Canned) != FoodState.None
			&& (acceptedState & FoodState.Canned) == FoodState.None)
		{
			relation = RelationPackUnitState;
		}
		else if (keyHeadPhrase.Count >= 2
			&& parsedTokens.Count == 1
			&& string.Equals(parsedTokens[0], IngredientLineResolver.SingularizeToken(keyHeadPhrase[0]), StringComparison.OrdinalIgnoreCase))
		{
			relation = RelationCompoundHeadLost;
		}
		else
		{
			var keyHeadParsed = FdcDescriptionParser.Parse(keyDesc, DatasetOf(keyTier));
			var acceptedHeadParsed = FdcDescriptionParser.Parse(acceptedDesc, DatasetOf(acceptedTier));
			var keyHead = SingularTokens(keyHeadParsed.HeadTerm);
			var acceptedHead = SingularTokens(acceptedHeadParsed.HeadTerm);
			var headsAgree = keyHead.SequenceEqual(acceptedHead, OrdinalIgnoreCaseComparer);

			if (headsAgree)
			{
				if (keyState != acceptedState)
				{
					relation = RelationStateMismatch;
				}
				else if (string.IsNullOrEmpty(acceptedTier) || string.IsNullOrEmpty(keyTier))
				{
					missingField = "actualDataTypes";
				}
				else if (!acceptedTier.Equals(keyTier, StringComparison.OrdinalIgnoreCase))
				{
					relation = RelationRowChoiceTier;
				}
				else
				{
					relation = RelationSameHeadOtherQualifier;
					var keyQualifiers = keyHeadParsed.Qualifiers.Select(IngredientLineResolver.SingularizeToken).ToHashSet(OrdinalIgnoreCaseComparer);
					var acceptedQualifiers = acceptedHeadParsed.Qualifiers.Select(IngredientLineResolver.SingularizeToken).ToHashSet(OrdinalIgnoreCaseComparer);
					keyOnlyQualifiers = keyQualifiers.Except(acceptedQualifiers).OrderBy(q => q, OrdinalIgnoreCaseComparer).ToArray();
					acceptedOnlyQualifiers = acceptedQualifiers.Except(keyQualifiers).OrderBy(q => q, OrdinalIgnoreCaseComparer).ToArray();
				}
			}
			else
			{
				relation = RelationSiblingFood;
			}
		}

		return new ClassificationResult
		{
			HoldoutId = line.HoldoutId,
			LineIndex = line.LineIndex,
			Set = line.Set,
			Relation = missingField is null ? relation : RelationOther,
			Site = site,
			OverrideKey = overrideKey,
			AcceptedTier = acceptedTier,
			KeyTier = keyTier,
			AcceptedState = acceptedState.ToString(),
			KeyState = keyState.ToString(),
			ParsedName = atom.ParsedName,
			KeyHead = string.Join(' ', keyHeadPhrase),
			AcceptedDesc = acceptedDesc,
			KeyDesc = keyDesc,
			RawText = line.RawText,
			MissingField = missingField,
			KeyOnlyQualifiers = keyOnlyQualifiers,
			AcceptedOnlyQualifiers = acceptedOnlyQualifiers,
		};
	}

	/// <summary>
	/// The key's head phrase: the leading normalised tokens of the key description, up to the first
	/// token production itself treats as state or a modifier (the lexicon's <c>ModifierWords</c>, or a
	/// non-<see cref="FoodState.None"/> result from <c>ExtractCandidateState</c>/<c>ExtractCandidateSatisfiers</c>
	/// on that token alone). <c>"Bread, crumbs, dry, grated, plain"</c> → <c>["bread", "crumbs"]</c>;
	/// <c>"Nuts, almonds, blanched"</c> → <c>["nuts", "almond"]</c> because <c>blanched</c> is a production
	/// modifier word. The single-token <see cref="FdcDescriptionParser"/> <c>HeadTerm</c> cannot express the
	/// two-word head the brief's §2 bread-crumbs example needs, so this phrase is what relation 3 compares.
	/// </summary>
	/// <param name="keyTokens">Normalised tokens of the key description.</param>
	/// <returns>The head phrase tokens.</returns>
	public IReadOnlyList<string> KeyHeadPhrase(IReadOnlyList<string> keyTokens)
	{
		ArgumentNullException.ThrowIfNull(keyTokens);

		var phrase = new List<string>();
		foreach (var token in keyTokens)
		{
			if (IsStateOrModifierToken(token))
			{
				break;
			}

			phrase.Add(token);
		}

		return phrase;
	}

	/// <summary>Normalises and singularises free text with the production helpers.</summary>
	/// <param name="text">The text to fold.</param>
	/// <returns>The singularised token list.</returns>
	public IReadOnlyList<string> SingularTokens(string? text) =>
		_normalizer.NormalizeToTokens(text).Select(IngredientLineResolver.SingularizeToken).ToArray();

	/// <summary>The production state mask of a token list: state ∪ satisfiers, the pair the matcher's own <c>StateAgrees</c> consumes.</summary>
	/// <param name="tokens">Normalised tokens.</param>
	/// <returns>The combined <see cref="FoodState"/> mask.</returns>
	public static FoodState CombinedState(IReadOnlyList<string> tokens)
	{
		ArgumentNullException.ThrowIfNull(tokens);
		return FdcMatcher.ExtractCandidateState(tokens) | FdcMatcher.ExtractCandidateSatisfiers(tokens);
	}

	/// <summary>
	/// Folds raw text for the <c>exact-overrides.json</c> raw-key lookup: lower-case, trimmed, everything
	/// from the first <c>(</c> dropped. That is the same fold the matcher's private
	/// <c>StripFromParenthesis</c> applies before <c>SpecialCases.TryGetRaw</c> (FdcMatcher.cs:165); the
	/// matcher method itself is private and this task may not widen it, so the fold is restated here and
	/// the lookup goes through the shipped <c>exact-overrides.json</c> key set itself.
	/// </summary>
	/// <param name="rawText">The raw line text.</param>
	/// <returns>The folded lookup key.</returns>
	public static string NormalizeForOverrideKey(string rawText)
	{
		ArgumentNullException.ThrowIfNull(rawText);

		var folded = rawText.Trim().ToLowerInvariant();
		var parenIndex = folded.IndexOf('(', StringComparison.Ordinal);
		return parenIndex >= 0 ? folded[..parenIndex].Trim() : folded;
	}

	/// <summary>Dataset enum for a trace dataType string; <see cref="FdcDataset.None"/> when unrecognised.</summary>
	/// <param name="dataType">The trace dataType token.</param>
	/// <returns>The matching <see cref="FdcDataset"/>.</returns>
	public static FdcDataset DatasetOf(string dataType) =>
		Enum.TryParse(dataType, ignoreCase: true, out FdcDataset dataset) ? dataset : FdcDataset.None;

	/// <summary>Rank of a dataset tier for the "which tier is higher" summary (Foundation &gt; SrLegacy &gt; Survey &gt; Branded).</summary>
	/// <param name="tier">The trace dataType token.</param>
	/// <returns>The rank; 0 when unrecognised.</returns>
	public static int TierRank(string tier) => tier switch
	{
		"Foundation" => 4,
		"SrLegacy" => 3,
		"Survey" => 2,
		"Branded" => 1,
		_ => 0,
	};

	[GeneratedRegex(@"\b(?:cans?|jars?)\b", RegexOptions.IgnoreCase)]
	private static partial Regex PackUnitRegex();

	private static TraceAtom PickAtom(IReadOnlyList<TraceAtom> atoms)
	{
		foreach (var atom in atoms)
		{
			if (atom.Outcome.Equals("accepted", StringComparison.OrdinalIgnoreCase))
			{
				return atom;
			}
		}

		return atoms.Count > 0 ? atoms[0] : new TraceAtom();
	}

	private static string FirstOrEmpty(IReadOnlyList<string> values) => values.Count > 0 ? values[0] : string.Empty;

	private (string Site, string OverrideKey) SiteFor(TraceAtom atom, string rawText) => atom.Path switch
	{
		"override" => (SiteOverride, _overrideKeys.IsKey(NormalizeForOverrideKey(rawText)) ? "yes" : "no"),
		"curated" => (SiteCurated, string.Empty),
		"ranker" => (atom.Reused ? SiteReuse : SiteRanker, string.Empty),
		_ => (string.Empty, string.Empty),
	};

	private bool IsStateOrModifierToken(string token)
	{
		if (FdcLexicon.Default.ModifierWords.Contains(token))
		{
			return true;
		}

		_singleTokenScratch.Clear();
		_singleTokenScratch.Add(token);
		return FdcMatcher.ExtractCandidateState(_singleTokenScratch) != FoodState.None
			|| FdcMatcher.ExtractCandidateSatisfiers(_singleTokenScratch) != FoodState.None;
	}
}
