{"content":"using System.Text.RegularExpressions;

using LetUsCook.AutoWrongCensus.Models;
using LetUsCook.Fdc;
using LetUsCook.Fdc.Lexicon;
using LetUsCook.Fdc.Matching;
using LetUsCook.Fdc.Parsing;
using LetUsCook.Fdc.Resolver;

namespace LetUsCook.AutoWrongCensus.Services;

/// <summary>
/// Classifies one auto-wrong trace line on two axes (F-428 P12.13 brief §4): the relation between
/// the accepted row (<c>actual*[0]</c>) and the key row (<c>expected*[0]</c>), and the decision site.
/// Every head, token, state and singularisation decision comes from the production helpers —
/// <see cref="FdcNormalizer.NormalizeToTokens(string)"/>, <see cref="FdcMatcher.ExtractCandidateState(IReadOnlyList{string})"/>,
/// <see cref="FdcMatcher.ExtractCandidateSatisfiers(IReadOnlyList{string})"/>, <see cref="FdcDescriptionParser.Parse(string, FdcDataset, string)"/>
/// and <see cref="IngredientLineResolver.SingularizeToken(string)"/> — never from a copy (D-014).
/// Not thread-safe: the runner classifies sequentially.
/// </summary>
public sealed partial class AutoWrongClassifier
{
	/// <summary>No labelled row.</summary>
	public const string RelationNoLabel = "no-label";

	/// <summary>Raw line names a can/jar unit; the key row is canned, the accepted row is not.</summary>
	public const string RelationPackUnitState = "pack-unit-state";

	/// <summary>The key head phrase has two or more words and parsedName is only its first word.</summary>
	public const string RelationCompoundHeadLost = "compound-head-lost";

	/// <summary>Head terms agree; the state masks differ.</summary>
	public const string RelationStateMismatch = "state-mismatch";

	/// <summary>Head terms and state agree; the dataset tiers differ.</summary>
	public const string RelationRowChoiceTier = "row-choice-tier";

	/// <summary>Head terms, state and tier agree; the qualifier sets differ.</summary>
	public const string RelationSameHeadOtherQualifier = "same-head-other-qualifier";

	/// <summary>The head terms differ.</summary>
	public const string RelationSiblingFood = "sibling-food";

	/// <summary>Nothing above held — a trace field a check needed was missing, or no shape matched.</summary>
	public const string RelationOther = "other";

	/// <summary>Ranker path with <c>reused</c>.</summary>
	public const string SiteReuse = "reuse";

	/// <summary>Override path.</summary>
	public const string SiteOverride = "override";

	/// <summary>Curated path.</summary>
	public const string SiteCurated = "curated";

	/// <summary>Ranker path without <c>reused</c>.</summary>
	public const string SiteRanker = "ranker";

	/// <summary>Trace field name for a missing accepted-row tier.</summary>
	public const string MissingFieldActualDataTypes = "actualDataTypes";

	/// <summary>Trace field name for a missing accepted row.</summary>
	public const string MissingFieldActualDescriptions = "actualDescriptions";

	[GeneratedRegex(@"\b(?:cans?|jars?)\b", RegexOptions.IgnoreCase)]
	private static partial Regex PackUnitRegex();

	private readonly FdcNormalizer _normalizer;
	private readonly ExactOverrideKeyIndex _overrideKeys;

	// Reusable one-element carrier so the per-token state probes do not allocate; the runner is
	// single-threaded (CA1051-adjacent note: the classifier is documented not thread-safe).
	private readonly string?[] _singleTokenScratch = new string?[1];

	/// <summary>Creates the classifier over the production normalizer and the override key index.</summary>
	/// <param name="normalizer">The production <see cref="FdcNormalizer"/>.</param>
	/// <param name="overrideKeys">Key set of <c>exact-overrides.json</c> for the override-site column.</param>
	public AutoWrongClassifier(FdcNormalizer normalizer, ExactOverrideKeyIndex overrideKeys)
	{
		ArgumentNullException.ThrowIfNull(normalizer);
		ArgumentNullException.ThrowIfNull(overrideKeys);
		_normalizer = normalizer;
		_overrideKeys = overrideKeys;
	}

	/// <summary>Classifies one trace line; only <c>auto &amp;&amp; !correct</c> lines carry a relation.</summary>
	/// <param name="line">The trace line.</param>
	/// <returns>Relation, site and the audit fields the TSV carries.</returns>
	public ClassificationResult Classify(TraceLine line)
	{
		ArgumentNullException.ThrowIfNull(line);

		var atom = PickAtom(line);
		var (site, overrideKey) = ClassifySite(line, atom);

		var keyDesc = First(line.ExpectedDescriptions);
		var acceptedDesc = First(line.ActualDescriptions);
		var keyTier = First(line.ExpectedDataTypes);
		var acceptedTier = First(line.ActualDataTypes);
		var parsedNameTokens = SingularPhrase(atom?.ParsedName);
		var keyTokens = _normalizer.NormalizeToTokens(keyDesc);
		var keyHeadPhrase = KeyHeadPhrase(keyTokens);

		var result = new ClassificationResult
		{
			HoldoutId = line.HoldoutId,
			LineIndex = line.LineIndex,
			Set = line.Set,
			Relation = RelationOther,
			Site = site,
			OverrideKey = overrideKey,
			AcceptedTier = acceptedTier,
			KeyTier = keyTier,
			AcceptedState = StateMask(acceptedDesc).ToString(),
			KeyState = StateMask(keyDesc).ToString(),
			ParsedName = atom?.ParsedName ?? string.Empty,
			KeyHead = string.Join(' ', keyHeadPhrase),
			AcceptedDesc = acceptedDesc,
			KeyDesc = keyDesc,
			RawText = line.RawText,
		};

		if (string.IsNullOrWhiteSpace(keyDesc))
		{
			return result with { Relation = RelationNoLabel };
		}

		var keyState = StateMask(keyDesc);
		var acceptedState = StateMask(acceptedDesc);

		// 2. pack-unit-state: a can/jar unit in the raw line, key canned, accepted not.
		if (PackUnitRegex().IsMatch(line.RawText)
			&& (keyState & FoodState.Canned) != 0
			&& (acceptedState & FoodState.Canned) == 0)
		{
			return result with { Relation = RelationPackUnitState };
		}

		// 3. compound-head-lost: multi-word key head phrase, parsedName is only its first word.
		if (keyHeadPhrase.Count >= 2
			&& parsedNameTokens.Count == 1
			&& string.Equals(parsedNameTokens[0], IngredientLineResolver.SingularizeToken(keyHeadPhrase[0]), StringComparison.OrdinalIgnoreCase))
		{
			return result with { Relation = RelationCompoundHeadLost };
		}

		var keyHead = SingularPhrase(FdcDescriptionParser.Parse(keyDesc, DatasetOf(keyTier)).HeadTerm);
		var acceptedHead = string.IsNullOrEmpty(acceptedDesc)
			? []
			: SingularPhrase(FdcDescriptionParser.Parse(acceptedDesc, DatasetOf(acceptedTier)).HeadTerm);
		var headsAgree = keyHead.SequenceEqual(acceptedHead, StringComparer.OrdinalIgnoreCase);

		if (!headsAgree)
		{
			if (string.IsNullOrEmpty(acceptedDesc))
			{
				return result with { Relation = RelationOther, MissingField = MissingFieldActualDescriptions };
			}

			return result with { Relation = RelationSiblingFood };
		}

		// 4. state-mismatch: heads agree, masks differ.
		if (keyState != acceptedState)
		{
			return result with { Relation = RelationStateMismatch };
		}

		// 5. row-choice-tier: heads and state agree, tier differs. Needs both tiers present (§8).
		if (string.IsNullOrEmpty(acceptedTier))
		{
			return result with { Relation = RelationOther, MissingField = MissingFieldActualDataTypes };
		}

		if (!string.Equals(keyTier, acceptedTier, StringComparison.OrdinalIgnoreCase))
		{
			return result with { Relation = RelationRowChoiceTier };
		}

		// 6. same-head-other-qualifier: heads, state and tier agree; record the qualifier difference.
		var keyQualifiers = QualifierSet(FdcDescriptionParser.Parse(keyDesc, DatasetOf(keyTier)).Qualifiers);
		var acceptedQualifiers = QualifierSet(FdcDescriptionParser.Parse(acceptedDesc, DatasetOf(acceptedTier)).Qualifiers);
		return result with
		{
			Relation = RelationSameHeadOtherQualifier,
			KeyOnlyQualifiers = keyQualifiers.Except(acceptedQualifiers, StringComparer.OrdinalIgnoreCase).ToArray(),
			AcceptedOnlyQualifiers = acceptedQualifiers.Except(keyQualifiers, StringComparer.OrdinalIgnoreCase).ToArray(),
		};
	}

	/// <summary>
	/// The key row's head phrase: the leading normalised tokens up to the first token production
	/// treats as a state or modifier word (<see cref="FdcLexicon.ModifierWords"/>,
	/// <see cref="FdcMatcher.ExtractCandidateState(IReadOnlyList{string})"/>,
	/// <see cref="FdcMatcher.ExtractCandidateSatisfiers(IReadOnlyList{string})"/>). This is the phrase
	/// the brief's relation 3 measures — e.g. <c>"Bread, crumbs, dry, grated, plain"</c> yields
	/// <c>["bread", "crumbs"]</c> and stops at <c>dry</c> — because the parser's single-token
	/// <see cref="ParsedFdcDescription.HeadTerm"/> cannot express a two-word head.
	/// </summary>
	/// <param name="tokens">Normalised tokens of the key description.</param>
	/// <returns>The head-phrase tokens (possibly empty).</returns>
	public IReadOnlyList<string> KeyHeadPhrase(IReadOnlyList<string> tokens)
	{
		ArgumentNullException.ThrowIfNull(tokens);
		var phrase = new List<string>(tokens.Count);
		foreach (var token in tokens)
		{
			if (CarriesStateToken(token))
			{
				break;
			}

			phrase.Add(token);
		}

		return phrase;
	}

	/// <summary>The row's production state mask: candidate state ∪ candidate satisfiers.</summary>
	/// <param name="description">The row description.</param>
	/// <returns>The combined mask.</returns>
	public FoodState StateMask(string description)
	{
		var tokens = _normalizer.NormalizeToTokens(description);
		return FdcMatcher.ExtractCandidateState(tokens) | FdcMatcher.ExtractCandidateSatisfiers(tokens);
	}

	/// <summary>
	/// Whether the resolver's own exact-phrase reuse rule would accept
	/// <paramref name="parsedName"/> against the linked master slug — the production
	/// <see cref="IngredientLineResolver.ShouldReuse(string, string)"/>, used for the reuse-site
	/// summary only; it never changes a relation or site.
	/// </summary>
	/// <param name="parsedName">The atom's parsed name.</param>
	/// <param name="linkedIngredientId">The linked ingredient master slug.</param>
	/// <returns>The production rule's verdict.</returns>
	public bool WouldProductionReuse(string parsedName, string linkedIngredientId)
	{
		var slug = IngredientLineParser.ComputeSlug(parsedName);
		return IngredientLineResolver.ShouldReuse(slug, linkedIngredientId);
	}

	/// <summary>
	/// Folds raw text to the <c>exact-overrides.json</c> lookup form: lower-case, trimmed, everything
	/// from the first <c>(</c> dropped. That cut mirrors production's private
	/// <see cref="FdcMatcher"/>.StripFromParenthesis (FdcMatcher.cs) — it is not reachable from the
	/// tool, so the one-line fold lives here and is stated in the report (brief §8).
	/// </summary>
	/// <param name="rawText">The raw line text.</param>
	/// <returns>The folded lookup text.</returns>
	public static string NormalizeForOverrideLookup(string rawText)
	{
		ArgumentNullException.ThrowIfNull(rawText);
		var folded = rawText.Trim().ToLowerInvariant();
		var paren = folded.IndexOf('(', StringComparison.Ordinal);
		return (paren >= 0 ? folded[..paren] : folded).Trim();
	}

	private static TraceAtom? PickAtom(TraceLine line)
	{
		if (line.Atoms.Count == 0)
		{
			return null;
		}

		foreach (var atom in line.Atoms)
		{
			if (atom.Outcome.Equals("accepted", StringComparison.OrdinalIgnoreCase))
			{
				return atom;
			}
		}

		return line.Atoms[0];
	}

	private (string Site, string OverrideKey) ClassifySite(TraceLine line, TraceAtom? atom)
	{
		var path = atom?.Path ?? string.Empty;
		switch (path)
		{
			case "override":
				return (SiteOverride, _overrideKeys.IsKey(NormalizeForOverrideLookup(line.RawText)) ? "yes" : "no");
			case "curated":
				return (SiteCurated, string.Empty);
			case "ranker":
				return (atom!.Reused ? SiteReuse : SiteRanker, string.Empty);
			default:
				return (string.Empty, string.Empty);
		}
	}

	private bool CarriesStateToken(string token)
	{
		if (FdcLexicon.Default.ModifierWords.Contains(token))
		{
			return true;
		}

		_singleTokenScratch[0] = token;
		return FdcMatcher.ExtractCandidateState(_singleTokenScratch) != FoodState.None
			|| FdcMatcher.ExtractCandidateSatisfiers(_singleTokenScratch) != FoodState.None;
	}

	private IReadOnlyList<string> SingularPhrase(string? text)
	{
		var tokens = _normalizer.NormalizeToTokens(text);
		var result = new string[tokens.Count];
		for (var i = 0; i < tokens.Count; i++)
		{
			result[i] = IngredientLineResolver.SingularizeToken(tokens[i]);
		}

		return result;
	}

	private static IReadOnlyList<string> QualifierSet(IReadOnlyList<string> qualifiers)
	{
		var result = new string[qualifiers.Count];
		for (var i = 0; i < qualifiers.Count; i++)
		{
			result[i] = IngredientLineResolver.SingularizeToken(qualifiers[i]);
		}

		return result;
	}

	private static FdcDataset DatasetOf(string tier) =>
		Enum.TryParse(tier, ignoreCase: true, out FdcDataset dataset) ? dataset : FdcDataset.None;

	private static string First(IReadOnlyList<string> values) => values.Count > 0 ? values[0] : string.Empty;
}
