{"content":"using System.Text.Json;

using LetUsCook.AutoWrongCensus.Models;
using LetUsCook.AutoWrongCensus.Options;
using LetUsCook.Fdc.Lexicon;
using LetUsCook.Fdc.Parsing;
using LetUsCook.Fdc.Resolver;

using Microsoft.Extensions.Options;

namespace LetUsCook.AutoWrongCensus.Services;

/// <summary>Runs one census or pairs invocation over a debug/batch trace.</summary>
public interface IAutoWrongCensusRunner
{
	/// <summary>Runs the configured subcommand.</summary>
	/// <param name="cancellationToken">Shutdown token.</param>
	/// <returns>0 on success; 1 on a missing file, a refused set, or an unusable invocation.</returns>
	Task<int> RunAsync(CancellationToken cancellationToken);
}

/// <summary>
/// Reads a HoldoutGate trace, keeps the auto-wrong lines (<c>auto &amp;&amp; !correct</c>), classifies
/// each through <see cref="AutoWrongClassifier"/>, and emits the TSV (stdout) plus the relation ×
/// site summary (stderr). Refuses any trace whose <c>set</c> is not <c>debug</c> or <c>batch</c> (D-029).
/// </summary>
public sealed class AutoWrongCensusRunner : IAutoWrongCensusRunner
{
	private static readonly JsonSerializerOptions JsonOptions = new(JsonSerializerDefaults.Web);

	private static readonly string[] TraceHeader =
	[
		"holdoutId", "lineIndex", "set", "relation", "site", "overrideKey", "acceptedTier", "keyTier",
		"acceptedState", "keyState", "parsedName", "keyHead", "acceptedDesc", "keyDesc", "rawText",
	];

	private readonly IOptions<AutoWrongCensusOptions> _options;
	private readonly AutoWrongClassifier _classifier;
	private readonly FdcNormalizer _normalizer;
	private readonly System.IO.TextWriter _output;
	private readonly System.IO.TextWriter _error;

	/// <summary>Creates the runner.</summary>
	/// <param name="options">Bound CLI options.</param>
	/// <param name="classifier">The relation/site classifier.</param>
	/// <param name="normalizer">The production normalizer (pairs head folding).</param>
	/// <param name="writers">Output/error writer pair.</param>
	public AutoWrongCensusRunner(
		IOptions<AutoWrongCensusOptions> options,
		AutoWrongClassifier classifier,
		FdcNormalizer normalizer,
		OutputWriters writers)
	{
		ArgumentNullException.ThrowIfNull(options);
		ArgumentNullException.ThrowIfNull(classifier);
		ArgumentNullException.ThrowIfNull(normalizer);
		ArgumentNullException.ThrowIfNull(writers);
		_options = options;
		_classifier = classifier;
		_normalizer = normalizer;
		_output = writers.Output;
		_error = writers.Error;
	}

	/// <inheritdoc />
	public async Task<int> RunAsync(CancellationToken cancellationToken)
	{
		var options = _options.Value;

		if (options.Command.Equals(CommandLineArgumentParser.CensusCommand, StringComparison.OrdinalIgnoreCase))
		{
			return await RunCensusAsync(options, cancellationToken).ConfigureAwait(false);
		}

		if (options.Command.Equals(CommandLineArgumentParser.PairsCommand, StringComparison.OrdinalIgnoreCase))
		{
			return await RunPairsAsync(options, cancellationToken).ConfigureAwait(false);
		}

		_error.WriteLine("Unusable arguments. Expected 'census <trace.jsonl>' or 'pairs <census.tsv> <trace.jsonl>'.");
		return 1;
	}

	private async Task<int> RunCensusAsync(AutoWrongCensusOptions options, CancellationToken cancellationToken)
	{
		if (!TryReadTrace(options.TracePath, out var lines, out var traceError))
		{
			_error.WriteLine(traceError);
			return 1;
		}

		var autoWrong = lines.Where(l => l.Auto && !l.Correct).ToArray();
		var results = new List<ClassificationResult>(autoWrong.Length);
		foreach (var line in autoWrong)
		{
			var result = _classifier.Classify(line);
			if (string.IsNullOrEmpty(result.Site))
			{
				_error.WriteLine($"refused: {line.HoldoutId}#{line.LineIndex} has an unknown atom path '{FirstAtomPath(line)}'.");
				return 1;
			}

			results.Add(result);
		}

		await _output.WriteLineAsync(Sanitize(TraceHeader)).ConfigureAwait(false);
		foreach (var result in results)
		{
			await _output.WriteLineAsync(Sanitize([
				result.HoldoutId, result.LineIndex.ToString(System.Globalization.CultureInfo.InvariantCulture), result.Set,
				result.Relation, result.Site, result.OverrideKey, result.AcceptedTier, result.KeyTier,
				result.AcceptedState, result.KeyState, result.ParsedName, result.KeyHead,
				result.AcceptedDesc, result.KeyDesc, result.RawText,
			])).ConfigureAwait(false);
		}

		WriteCensusSummary(lines.Count, results);
		return 0;
	}

	private async Task<int> RunPairsAsync(AutoWrongCensusOptions options, CancellationToken cancellationToken)
	{
		if (!TryReadTrace(options.TracePath, out var lines, out var traceError))
		{
			_error.WriteLine(traceError);
			return 1;
		}

		if (!File.Exists(options.CensusTsvPath))
		{
			_error.WriteLine($"refused: census TSV not found at '{options.CensusTsvPath}'.");
			return 1;
		}

		var traceByPosition = lines.ToDictionary(l => (l.HoldoutId, l.LineIndex));
		var selected = new List<(string HoldoutId, int LineIndex)>();
		var missingColumns = false;

		using (var reader = new StreamReader(options.CensusTsvPath))
		{
			var headerLine = await reader.ReadLineAsync(cancellationToken).ConfigureAwait(false);
			if (headerLine is null)
			{
				_error.WriteLine($"refused: census TSV '{options.CensusTsvPath}' is empty.");
				return 1;
			}

			var header = headerLine.Split('\t');
			var idIndex = Array.IndexOf(header, "holdoutId");
			var indexIndex = Array.IndexOf(header, "lineIndex");
			var blockerIndex = Array.IndexOf(header, "blocker");
			var routeIndex = Array.IndexOf(header, "route");
			if (idIndex < 0 || indexIndex < 0 || blockerIndex < 0 || routeIndex < 0)
			{
				missingColumns = true;
			}
			else
			{
				string? rowLine;
				while ((rowLine = await reader.ReadLineAsync(cancellationToken).ConfigureAwait(false)) is not null)
				{
					var cells = rowLine.Split('\t');
					if (cells.Length <= Math.Max(Math.Max(idIndex, indexIndex), Math.Max(blockerIndex, routeIndex)))
					{
						continue;
					}

					if (cells[blockerIndex] == "window" && (cells[routeIndex] == "compound" || cells[routeIndex] == "other")
						&& int.TryParse(cells[indexIndex], System.Globalization.NumberStyles.Integer, System.Globalization.CultureInfo.InvariantCulture, out var lineIndex))
					{
						selected.Add((cells[idIndex], lineIndex));
					}
				}
			}
		}

		if (missingColumns)
		{
			_error.WriteLine($"refused: census TSV '{options.CensusTsvPath}' lacks holdoutId/lineIndex/blocker/route columns.");
			return 1;
		}

		var unmatched = 0;
		await _output.WriteLineAsync(Sanitize(["holdoutId", "lineIndex", "parsedNameHead", "keyHead", "rawText"])).ConfigureAwait(false);
		foreach (var (holdoutId, lineIndex) in selected)
		{
			if (!traceByPosition.TryGetValue((holdoutId, lineIndex), out var line))
			{
				unmatched++;
				continue;
			}

			var atom = line.Atoms.Count > 0 ? line.Atoms[0] : null;
			var parsedNameHead = atom is null
				? string.Empty
				: string.Join(' ', SingularizeAll(_normalizer.NormalizeToTokens(atom.ParsedName)));
			var keyDesc = line.ExpectedDescriptions.Count > 0 ? line.ExpectedDescriptions[0] : string.Empty;
			var keyHead = string.Join(' ', _classifier.KeyHeadPhrase(_normalizer.NormalizeToTokens(keyDesc)));
			await _output.WriteLineAsync(Sanitize([holdoutId, lineIndex.ToString(System.Globalization.CultureInfo.InvariantCulture), parsedNameHead, keyHead, line.RawText])).ConfigureAwait(false);
		}

		_error.WriteLine($"pairs: selected={selected.Count} emitted={selected.Count - unmatched} unmatchedInTrace={unmatched}");
		return 0;
	}

	private bool TryReadTrace(string path, out TraceLine[] lines, out string error)
	{
		if (string.IsNullOrWhiteSpace(path) || !File.Exists(path))
		{
			lines = [];
			error = $"refused: trace file not found at '{path}'.";
			return false;
		}

		var all = new List<TraceLine>();
		var lineNumber = 0;
		foreach (var raw in File.ReadLines(path))
		{
			lineNumber++;
			if (raw.Length == 0)
			{
				continue;
			}

			TraceLine? parsed;
			try
			{
				parsed = JsonSerializer.Deserialize<TraceLine>(raw, JsonOptions);
			}
			catch (JsonException ex)
			{
				lines = [];
				error = $"refused: trace line {lineNumber} is not valid JSON: {ex.Message}";
				return false;
			}

			if (parsed is null)
			{
				lines = [];
				error = $"refused: trace line {lineNumber} deserialized to null.";
				return false;
			}

			all.Add(parsed);
		}

		lines = all.ToArray();

		var refused = all.FirstOrDefault(l => !l.Set.Equals("debug", StringComparison.OrdinalIgnoreCase) && !l.Set.Equals("batch", StringComparison.OrdinalIgnoreCase));
		if (refused is not null)
		{
			error = $"refused: trace set '{refused.Set}' is not debug or batch (D-029: no sealed read).";
			return false;
		}

		error = string.Empty;
		return true;
	}

	private void WriteCensusSummary(int traceLineCount, IReadOnlyList<ClassificationResult> results)
	{
		var set = results.Count > 0 ? results[0].Set : string.Empty;
		_error.WriteLine($"census: set={set} traceLines={traceLineCount} autoWrongLines={results.Count}");

		_error.WriteLine("relation\tsite\tcount");
		foreach (var group in results.GroupBy(r => (r.Relation, r.Site)).OrderBy(g => g.Key.Relation, StringComparer.Ordinal).ThenBy(g => g.Key.Site, StringComparer.Ordinal))
		{
			_error.WriteLine($"{group.Key.Relation}\t{group.Key.Site}\t{group.Count()}");
		}

		var other = results.Count(r => r.Relation == AutoWrongClassifier.RelationOther);
		var otherShare = results.Count == 0 ? 0.0 : 100.0 * other / results.Count;
		_error.WriteLine($"other share: {other}/{results.Count} ({otherShare:0.0}%)");

		foreach (var missing in results.Where(r => r.MissingField is not null).GroupBy(r => r.MissingField!).OrderBy(g => g.Key, StringComparer.Ordinal))
		{
			_error.WriteLine($"missing field: {missing.Key}={missing.Count()}");
		}

		var overrideLines = results.Where(r => r.Site == AutoWrongClassifier.SiteOverride).ToArray();
		if (overrideLines.Length > 0)
		{
			var hits = overrideLines.Count(r => r.OverrideKey == "yes");
			_error.WriteLine($"overrideKey in exact-overrides.json: yes={hits} no={overrideLines.Length - hits}");
		}

		var tierGroups = results.Where(r => r.Relation == AutoWrongClassifier.RelationRowChoiceTier)
			.GroupBy(r => TierRank(r.KeyTier) > TierRank(r.AcceptedTier) ? "key higher" : "accepted higher");
		foreach (var tierGroup in tierGroups)
		{
			_error.WriteLine($"row-choice-tier {tierGroup.Key}: {tierGroup.Count()}");
		}

		foreach (var qualifierDiff in results.Where(r => r.Relation == AutoWrongClassifier.RelationSameHeadOtherQualifier))
		{
			_error.WriteLine($"same-head-other-qualifier {qualifierDiff.HoldoutId}#{qualifierDiff.LineIndex}: keyOnly=[{string.Join(' ', qualifierDiff.KeyOnlyQualifiers ?? [])}] acceptedOnly=[{string.Join(' ', qualifierDiff.AcceptedOnlyQualifiers ?? [])}]");
		}

		WriteReuseShouldReuseSummary(results);
	}

	// Production reuse-rule check for the reuse-site lines: would IngredientLineResolver.ShouldReuse
	// have accepted the linked master for this line's own parsed name? Reported only — it never
	// changes the relation or site classification.
	private void WriteReuseShouldReuseSummary(IReadOnlyList<ClassificationResult> results)
	{
		var reuseLines = results.Where(r => r.Site == AutoWrongClassifier.SiteReuse).ToArray();
		if (reuseLines.Length == 0)
		{
			return;
		}

		var falseCount = 0;
		foreach (var result in reuseLines)
		{
			var link = _linkedIngredientIdByPosition[(result.HoldoutId, result.LineIndex)];
			if (link is null)
			{
				continue;
			}

			if (!IngredientLineResolver.ShouldReuse(IngredientLineParser.ComputeSlug(result.ParsedName), link))
			{
				falseCount++;
			}
		}

		_error.WriteLine($"reuse lines with ShouldReuse(parsedName, linkedIngredientId)=false: {falseCount}/{reuseLines.Length}");
	}

	private static int TierRank(string tier) => tier.ToLowerInvariant() switch
	{
		"foundation" => 4,
		"srllegacy" => 3,
		"srlegacy" => 3,
		"survey" => 2,
		"branded" => 1,
		_ => 0,
	};

	private static string FirstAtomPath(TraceLine line) => line.Atoms.Count > 0 ? line.Atoms[0].Path : string.Empty;

	private static IReadOnlyList<string> SingularizeAll(IReadOnlyList<string> tokens) =>
		Array.ConvertAll(tokens.ToArray(), IngredientLineResolver.SingularizeToken);

	private static string Sanitize(string[] cells) => string.Join('\t', cells.Select(Sanitize));

	private static string Sanitize(string text) => text.Replace('\t', ' ').Replace('\n', ' ').Replace('\r', ' ');

	private Dictionary<(string HoldoutId, int LineIndex), string?> _linkedIngredientIdByPosition = new();
}
